globalThis.__snapbackHandlers = { "changeAvatarMutation": (async (ctx, args) => {
    const profile = await ctx.db.get('profiles', args.profileId);
    if (!profile || profile.ownerId !== ctx.auth.userId) {
      throw new Error('Profile is unavailable for this persona.');
    }
    await ctx.db.patch('profiles', profile._id, {
      avatar: await ctx.assets.attach(args.avatar, { upload: 'profileImageUpload' }),
    });
    return profile._id;
  }) };

globalThis.__snapbackHandlers = { "createPostMutation": (async (ctx, args) => {
    const body = args.body.trim();
    if (body.length === 0 || body.length > 280) {
      throw new Error('Post text must be between 1 and 280 characters.');
    }
    return {
      _id: await ctx.db.insert('posts', { body }),
    };
  }) };

globalThis.__snapbackHandlers = { "ensureProfile": (async (ctx, args) => {
    const existing = await ctx.db
      .query('profiles')
      .withIndex('by_owner')
      .eq('ownerId', ctx.auth.userId)
      .first();
    if (existing) {
      if (existing.displayName !== args.displayName) {
        await ctx.db.patch('profiles', existing._id, { displayName: args.displayName });
      }
      return existing._id;
    }
    // ownerId is host-stamped on owner-policy inserts; authored owner
    // input is refused by the ownership-composition rules.
    return ctx.db.insert('profiles', { displayName: args.displayName });
  }) };
